import unittest

from logtool.summary import summarize_errors


class HeldOutLogTests(unittest.TestCase):
    def setUp(self):
        self.result = summarize_errors("data/events.log")

    def test_level_counts(self):
        self.assertEqual(self.result["by_level"], {
            "DEBUG": 87, "INFO": 235, "WARN": 76, "ERROR": 133, "CRITICAL": 89,
        })

    def test_component_counts_cover_error_levels_only(self):
        self.assertEqual(self.result["by_component"], {
            "api": 80, "auth": 26, "scheduler": 26, "storage": 39, "worker": 51,
        })

    def test_error_totals_and_malformed_counts(self):
        self.assertEqual(self.result["total_errors"], 222)
        self.assertEqual(self.result["malformed"], 17)

    def test_first_error_message(self):
        self.assertEqual(self.result["first_error"], "request completed")


if __name__ == "__main__":
    unittest.main()
